const sd = $getWorkflowStaticData('global');
sd.history = sd.history || [];
const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
const runId = 'brm-' + stamp + '-' + Math.random().toString(36).slice(2, 6);
return [{ json: {
  run_id: runId,
  started_at: new Date().toISOString(),
  gemini_base: $vars.GEMINI_API_BASE || 'https://generativelanguage.googleapis.com',
  gemini_model: $vars.GEMINI_MODEL || 'gemini-2.5-flash',
  clip_count: Number($vars.CLIP_COUNT || 3),
  kling_api_base: $vars.KLING_API_BASE || 'https://api.klingai.com',
  kling_model: $vars.KLING_MODEL || 'kling-v2-5-turbo',
  kling_mode: $vars.KLING_MODE || 'std',
  kling_duration: String($vars.KLING_DURATION || '10'),
  kling_max_polls: Number($vars.KLING_MAX_POLLS || 20),
  post_mode: String($vars.POST_MODE || 'INBOX').toUpperCase(),
  privacy_level: $vars.PRIVACY_LEVEL || 'SELF_ONLY',
  merge_clips: String($vars.ENABLE_FFMPEG_MERGE || 'false').toLowerCase() === 'true',
  ffmpeg_path: $vars.FFMPEG_PATH || 'ffmpeg',
  output_dir: $vars.OUTPUT_DIR || '/tmp',
  notify_url: $vars.NOTIFY_WEBHOOK_URL || '',
  history: sd.history.slice(-40)
} }];

const c = $input.first().json;
const sys = [
'You are the creative engine of "Brainrot Maroc", a TikTok channel that publishes exactly ONE ORIGINAL vertical comedy short per day in Moroccan Darija.',
'',
'HARD OUTPUT RULES:',
'- Reply with JSON only, matching the supplied schema. No markdown fences.',
'- kling_prompt: one English visual prompt for a camera-realistic 9:16 vertical shot. Describe ONE continuous scene: subject, wardrobe, location, action, camera movement, lighting, mood. Never put text, logos, watermarks, or subtitles on screen. Never use real or fictional copyrighted characters, brand names, or any real-person likeness.',
'- clip_prompts: exactly ' + c.clip_count + ' prompts. They are ONE continuous scene cut into beats: clip 1 is the hook (first second), the middle clips escalate, the last clip is the punchline. Keep identical characters, wardrobe, location and lighting across every clip.',
'- voiceover_darija: ORIGINAL Moroccan Darija script, maximum 75 words, written in Latin characters (Arabizi) with everyday Darija and French slang. It must be a joke or a reaction, never a plain description of the image. No hate speech, no slurs, no insults against any group or region, no politics, no religion, no sexual content, no violence, no self-harm, no drugs or alcohol, no dangerous stunts.',
'- caption: maximum 120 characters, punchy, honest, no fake promises, no hashtags inside it.',
'- hashtags: 3 to 5 items. MUST include #Morocco, #Maroc and #TikTokMaroc. At most 2 extra relevant tags. No spammy or banned tags.',
'- safety: you must self-check. Set passed=false if the concept touches ANY of: hate speech or slurs, sexual content, minors in a risky or sexualised context, violence or gore, dangerous stunts or self-harm, drugs or alcohol, politics, religion, impersonation of a real person, copyrighted characters or music, medical or financial claims, or fear-mongering.',
'',
'STYLE:',
'- Everyday Morocco: cafe and hanout, grand taxi and tram, football culture, family and neighbours, street food, school and bureau, weddings, rain and traffic, power cuts, exam season, Ramadan evenings, beach days.',
'- Absurd escalation, fast cuts, a hook that lands in under one second, a clear punchline at the end.',
'- Fictional generic characters only. Punch up at situations, never down at people, regions, or communities.',
'',
'ORIGINALITY:',
'- Never copy or imitate another creator, trend audio, or existing meme format.',
'- Do not reuse any of these recent concepts: ' + JSON.stringify(c.history)
].join('\n');
const user = 'Produce one fresh, safe, original Brainrot Maroc concept for ' + new Date().toISOString().slice(0, 10) + '. Make the hook land in under one second.';
const schema = {
  type: 'OBJECT',
  properties: {
    concept_title: { type: 'STRING' },
    setting: { type: 'STRING' },
    hook: { type: 'STRING' },
    kling_prompt: { type: 'STRING' },
    clip_prompts: { type: 'ARRAY', items: { type: 'STRING' } },
    negative_prompt: { type: 'STRING' },
    voiceover_darija: { type: 'STRING' },
    caption: { type: 'STRING' },
    hashtags: { type: 'ARRAY', items: { type: 'STRING' } },
    safety: { type: 'OBJECT', properties: { passed: { type: 'BOOLEAN' }, flags: { type: 'ARRAY', items: { type: 'STRING' } }, notes: { type: 'STRING' } } },
    retention_note: { type: 'STRING' }
  },
  required: ['concept_title', 'setting', 'hook', 'kling_prompt', 'clip_prompts', 'negative_prompt', 'voiceover_darija', 'caption', 'hashtags', 'safety', 'retention_note']
};
const body = {
  systemInstruction: { parts: [{ text: sys }] },
  contents: [{ role: 'user', parts: [{ text: user }] }],
  generationConfig: { responseMimeType: 'application/json', responseSchema: schema, temperature: 1.0, topP: 0.95 },
  safetySettings: [
    { category: 'HARM_CATEGORY_HARASSMENT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
    { category: 'HARM_CATEGORY_HATE_SPEECH', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
    { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
    { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' }
  ]
};
return [{ json: { requestBody: body, cfg: c } }];

const cfg = $('Run Config').first().json;
const resp = $input.first().json;
const issues = [];
if (resp.error) issues.push('Gemini API error: ' + JSON.stringify(resp.error).slice(0, 300));
const cand = (resp.candidates && resp.candidates[0]) || {};
const parts = (cand.content && cand.content.parts) || [];
const text = parts.map(p => p.text || '').join('');
let o = null;
try {
  const m = text.match(/\{[\s\S]*\}/);
  o = JSON.parse(m ? m[0] : text);
} catch (e) {
  return [{ json: { ok: false, issues: ['Gemini reply is not valid JSON. Raw head: ' + text.slice(0, 300)], cfg: cfg } }];
}
const req = ['concept_title', 'setting', 'hook', 'kling_prompt', 'clip_prompts', 'voiceover_darija', 'caption', 'hashtags', 'safety'];
for (const k of req) { if (o[k] === undefined || o[k] === null || o[k] === '') issues.push('Missing field: ' + k); }
const vo = String(o.voiceover_darija || '');
const voWords = vo.trim().split(/\s+/).filter(Boolean).length;
if (voWords > 75) issues.push('Voiceover too long: ' + voWords + ' words (max 75).');
if (voWords < 5) issues.push('Voiceover too short: ' + voWords + ' words.');
const cap = String(o.caption || '');
if (cap.length > 120) issues.push('Caption too long: ' + cap.length + ' chars (max 120).');
if (cap.length < 10) issues.push('Caption too short.');
let tags = (Array.isArray(o.hashtags) ? o.hashtags : []).map(t => String(t).trim()).filter(Boolean).map(t => (t.startsWith('#') ? t : '#' + t));
tags = Array.from(new Set(tags));
if (tags.length < 3 || tags.length > 5) issues.push('Hashtag count invalid: ' + tags.length + ' (need 3 to 5).');
const need = ['#morocco', '#maroc', '#tiktokmaroc'];
for (const n of need) { if (!tags.some(t => t.toLowerCase() === n)) issues.push('Missing required hashtag: ' + n); }
const banned = /\b(kill|suicide|rape|nude|porn|sexual|isis|jihad|cocaine|heroin|weed|hashish|zamel|sahbi\s+khwa)\b/i;
const blob = [o.kling_prompt, vo, cap, tags.join(' '), (o.concept_title || '')].join(' ');
if (banned.test(blob)) issues.push('Banned term matched in generated content.');
const sf = o.safety || {};
if (sf.passed !== true) issues.push('Model safety check failed. Flags: ' + JSON.stringify(sf.flags || []) + ' Notes: ' + (sf.notes || ''));
let clips = (Array.isArray(o.clip_prompts) && o.clip_prompts.length) ? o.clip_prompts.map(String) : [String(o.kling_prompt || '')];
if (clips.length < cfg.clip_count) {
  const last = clips[clips.length - 1];
  while (clips.length < cfg.clip_count) clips.push(last);
}
clips = clips.slice(0, cfg.clip_count);
const concept = {
  run_id: cfg.run_id,
  concept_title: o.concept_title,
  setting: o.setting,
  hook: o.hook,
  kling_prompt: o.kling_prompt,
  clip_prompts: clips,
  negative_prompt: o.negative_prompt || 'text, watermark, logo, subtitles, copyrighted character, brand name, violence, sexual content, gore, dangerous stunt, real person likeness',
  voiceover_darija: vo,
  voiceover_words: voWords,
  caption: cap,
  caption_chars: cap.length,
  hashtags: tags,
  safety: sf,
  retention_note: o.retention_note || ''
};
return [{ json: { ok: issues.length === 0, issues: issues, concept: concept, cfg: cfg } }];

const j = $input.first().json;
const url = j.cfg.notify_url || '';
const payload = { event: 'concept_rejected', run_id: j.cfg.run_id, issues: j.issues, at: new Date().toISOString() };
let sent = false;
if (url) {
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: url, body: payload, json: true, timeout: 20000 });
    sent = true;
  } catch (e) { sent = false; }
}
return [{ json: Object.assign({}, payload, { notified: sent }) }];

const sd = $getWorkflowStaticData('global');
const j = $input.first().json;
sd.history = sd.history || [];
sd.history.push(j.concept.concept_title + ' :: ' + j.concept.setting);
sd.history = sd.history.slice(-40);
return [{ json: j }];

const j = $input.first().json;
const c = j.cfg;
return [{ json: {
  run_id: c.run_id,
  clip_prompts: j.concept.clip_prompts,
  negative_prompt: j.concept.negative_prompt,
  model_name: c.kling_model,
  mode: c.kling_mode,
  duration: c.kling_duration,
  aspect_ratio: '9:16',
  cfg_scale: 0.5,
  api_base: c.kling_api_base,
  max_polls: c.kling_max_polls,
  concept: j.concept
} }];

const sd = $getWorkflowStaticData('global');
const j = $input.first().json;
const url = (j.notify_url || $('Run Config').first().json.notify_url || '');
const payload = { event: 'video_generation_failed', run_id: $('Run Config').first().json.run_id, status: j.status, error: j.error, clips: j.clips, at: new Date().toISOString() };
let sent = false;
if (url) { try { await this.helpers.httpRequest({ method: 'POST', url: url, body: payload, json: true, timeout: 20000 }); sent = true; } catch (e) { sent = false; } }
return [{ json: Object.assign({}, payload, { notified: sent }) }];

const cfg = $('Run Config').first().json;
const j = $input.first().json;
const urls = j.video_urls || [];
const inputs = urls.map(u => '-i "' + u + '"').join(' ');
const maps = urls.map((u, i) => '[' + i + ':v]').join('');
const out = cfg.output_dir.replace(/[\\/]+$/, '') + '/' + cfg.run_id + '.mp4';
const cmd = cfg.ffmpeg_path + ' -y ' + inputs + ' -filter_complex "' + maps + 'concat=n=' + urls.length + ':v=1:a=0[v]" -map "[v]" -c:v libx264 -pix_fmt yuv420p -r 30 -vf scale=1080:1920 "' + out + '"';
return [{ json: Object.assign({}, j, { ffmpeg_command: cmd, merged_path: out, merged_clips: urls.length }) }];

const cfg = $('Run Config').first().json;
const concept = $('Prepare Kling Input').first().json.concept;
const v = $input.first().json;
const merged = v.merged_path || null;
const useLocal = !!(merged && cfg.merge_clips);
return [{ json: {
  run_id: cfg.run_id,
  video_url: useLocal ? null : v.video_url,
  local_video_path: useLocal ? merged : null,
  merged: useLocal,
  caption: concept.caption,
  hashtags: concept.hashtags.join(' '),
  post_mode: cfg.post_mode,
  privacy_level: cfg.privacy_level,
  cover_timestamp_ms: 1000,
  concept: concept,
  kling: { status: v.status, video_urls: v.video_urls, clip_count: v.clip_count, approx_total_seconds: v.approx_total_seconds, error: v.error }
} }];

const j = $input.first().json;
const url = $('Run Config').first().json.notify_url || '';
const payload = { event: 'approval_required', run_id: j.run_id, caption: j.caption, hashtags: j.hashtags, video_url: j.video_url, privacy_level: j.privacy_level, approve_url: $execution.resumeUrl, question: 'Publish this video to TikTok publicly? Call approve_url to confirm.', at: new Date().toISOString() };
let sent = false;
if (url) { try { await this.helpers.httpRequest({ method: 'POST', url: url, body: payload, json: true, timeout: 20000 }); sent = true; } catch (e) { sent = false; } }
return [{ json: Object.assign({}, j, { approval_requested: true, notified: sent, approve_url: $execution.resumeUrl }) }];

const cfg = $('Run Config').first().json;
const tt = $input.first().json;
const pay = $('Build TikTok Payload').first().json;
const kling = $('Build TikTok Payload').first().json.kling;
const report = {
  run_id: cfg.run_id,
  finished_at: new Date().toISOString(),
  concept: { title: pay.concept.concept_title, setting: pay.concept.setting, hook: pay.concept.hook, caption: pay.concept.caption, caption_chars: pay.concept.caption_chars, hashtags: pay.concept.hashtags, voiceover_words: pay.concept.voiceover_words, voiceover: pay.concept.voiceover_darija, safety: pay.concept.safety },
  video: { status: kling.status, clip_count: kling.clip_count, approx_total_seconds: kling.approx_total_seconds, urls: kling.video_urls, error: kling.error },
  publish: { status: tt.status, visibility: tt.visibility, post_mode: tt.post_mode, publish_id: tt.publish_id, tiktok_status: tt.tiktok_status, error: tt.error, note: tt.note },
  merged_local_file: pay.local_video_path
};
const url = cfg.notify_url || '';
let sent = false;
if (url) { try { await this.helpers.httpRequest({ method: 'POST', url: url, body: { event: 'run_complete', report: report }, json: true, timeout: 20000 }); sent = true; } catch (e) { sent = false; } }
const md = [
'# Brainrot Maroc run ' + cfg.run_id,
'',
'Concept: ' + report.concept.title + ' (' + report.concept.setting + ')',
'Hook: ' + report.concept.hook,
'Caption (' + report.concept.caption_chars + ' chars): ' + report.concept.caption,
'Tags: ' + report.concept.hashtags.join(' '),
'Voiceover (' + report.concept.voiceover_words + ' words): ' + report.concept.voiceover,
'',
'Video: ' + report.video.status + ' | clips: ' + report.video.clip_count + ' | ~' + report.video.approx_total_seconds + 's',
'Errors: ' + (report.video.error || 'none'),
'',
'Publish: ' + report.publish.status + ' | visibility: ' + report.publish.visibility + ' | mode: ' + report.publish.post_mode,
report.publish.note || ''
].join('\n');
return [{ json: { report: report, report_markdown: md, notified: sent } }];
